import type { Metadata } from "next";
import { siteConfig } from "@/config/site";

/** "https://www.greenfield.example/news" for "/news". Structured data and sitemaps need absolute URLs. */
export function absoluteUrl(path: string): string {
  return new URL(path, siteConfig.url).toString();
}

/** The site-wide share image, generated by app/opengraph-image.tsx. */
export const DEFAULT_OG_IMAGE = { url: "/opengraph-image", width: 1200, height: 630, alt: siteConfig.name };

/**
 * Open Graph fields every page shares. A page's `openGraph` replaces its parent's completely,
 * including the image that app/opengraph-image.tsx adds at the root, so each page repeats them.
 */
export const baseOpenGraph = {
  siteName: siteConfig.name,
  locale: "en_GB",
  type: "website" as const,
};

type PageMetadataOptions = {
  title: string;
  description: string;
  /** The page's own path, e.g. "/news". Becomes the canonical URL. */
  path: string;
  /** Extra Open Graph fields, e.g. `{ type: "article", publishedTime }`. */
  openGraph?: Metadata["openGraph"];
  /**
   * True for routes with their own opengraph-image file (news articles, events). Those must not
   * name the default image: an image set here would replace the route's own one.
   */
  ownImage?: boolean;
};

/**
 * Title, description, canonical URL and Open Graph tags for a page.
 *
 * The canonical URL never includes search params, so filtered and paginated lists (/news?page=2)
 * point search engines at the main list; the items themselves are all in the sitemap.
 */
export function pageMetadata({ title, description, path, openGraph, ownImage }: PageMetadataOptions): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      ...baseOpenGraph,
      ...(!ownImage && { images: [DEFAULT_OG_IMAGE] }),
      title,
      description,
      url: path,
      ...openGraph,
    },
  };
}
